-- ---------------------------------------------------------------  CREATE PROCEDURE [bud].[jsGetPendingBudgets]      @userId INT = 78,      @company INT = 1,   @month VARCHAR(MAX) = '08-2026'  AS  BEGIN      SET NOCOUNT ON;   -- EXEC bud.jsGetPendingBudgetApprovalsRelatedToUser @userId, @company      -- Step 1: Get all stages assigned to this user for budget approval      DECLARE @stageTable TABLE (stageId INT)      INSERT INTO @stageTable      SELECT jus.stageId       FROM jsUserStage jus      INNER JOIN jsStageTemplate st ON jus.stageId = st.stageId      INNER JOIN jsTemplate t ON st.templateId = t.id      INNER JOIN jsTemplateApproval ta ON t.id = ta.templateId      WHERE jus.userId = @userId        AND t.company = @company        AND ta.approvalId = 5        AND (              (jus.startTime IS NULL AND jus.endDate IS NULL)              OR (                  jus.startTime IS NOT NULL AND                   jus.endDate IS NOT NULL AND                  jus.status = 1 AND                  GETDATE() BETWEEN jus.startTime AND jus.endDate              )            );        -- Step 2: Get pending budgets (status = 'P') in these stages      DECLARE @budgetTable TABLE (          docId INT,          stageId INT,          templateId INT,          objType VARCHAR(50),          company NVARCHAR(200),          lineNum INT,          visOrder INT      );        INSERT INTO @budgetTable      SELECT           jd.id AS docId,          jd.currentStageId,          jd.templateId,          d.objType,          CAST(d.company AS NVARCHAR(200)) as company,          d.lineNum,          d.visOrder      FROM bud.jsDocEntry jd      INNER JOIN bud.jsDocEnrtyDetail d ON jd.id = d.docId      INNER JOIN @stageTable st ON jd.currentStageId = st.stageId      WHERE jd.status = 'P';          -- Step 3: Remove budgets already acted upon by this user at this stage      DELETE b      FROM @budgetTable b      INNER JOIN bud.jsBudgetStatusWorkflow wf          ON b.docId = wf.docId          AND b.stageId = wf.stageId          AND b.templateId = wf.templateId          AND wf.userId = @userId;          -- Step 4: Return specific budget lines with matching lineNum and visOrder      SELECT           jd.id AS BudgetId,          b.objType,          b.company,    bt.DocEntry,          bt.ObjectName,          bt.CardCode,          bt.CardName,          bt.BUDGET,          --bt.SUB_BUDGET,          bt.DocDate,          SUM(          CASE               WHEN b.objType = 19 THEN bt.AMOUNT * -1              ELSE bt.AMOUNT          END    ) AS TotalAmount,    bt.CURRENTMONTH      FROM @budgetTable b      INNER JOIN bud.jsDocEntry jd ON b.docId = jd.id      INNER JOIN bud.jsBudgetTable_Dedup bt           ON bt.docEntry = jd.docEntry          AND bt.ObjType = b.objType          AND bt.Branch = b.company          AND bt.LineNum = b.lineNum          AND bt.VisOrder = b.visOrder      GROUP BY           jd.id,bt.DocEntry, b.objType, b.company, bt.ObjectName, bt.CardCode, bt.CardName, bt.DocDate,bt.CURRENTMONTH,bt.BUDGET   HAVING bt.CURRENTMONTH = @month  END;
